import {gridFor,maxHeight,fits,dividerBOM,validPlan} from './divider-layout.mjs';
import {matchModelDirectory} from './local-models.mjs?revision=directory-tree-2';
import {writeZip} from './zip.mjs';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const [data,cat,estimates]=await Promise.all(['dividers-data.json','catalog.json','estimates.json'].map(async u=>{const r=await fetch(u);if(!r.ok)throw Error('模型索引读取失败');return r.json();}));
const KEY='vault-divider-layouts-v1';let saved={},state,selected=null,history=[],drag=null,linked=new Map(),local=false,busy=false;
try{saved=JSON.parse(localStorage.getItem(KEY)||'{}');if(!saved||typeof saved!=='object'||Array.isArray(saved))saved={};}catch{}
const key=s=>s.family+s.depth+'F'+s.floor;
const blank=spec=>({version:1,spec,height:34.5,pin:'loose',items:[]});
const grid=()=>gridFor(state.spec,data),clone=x=>JSON.parse(JSON.stringify(x));
let timer;function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('toast').classList.remove('show'),3500);}
function save(){saved[key(state.spec)]=clone(state);try{localStorage.setItem(KEY,JSON.stringify(saved));$('saveState').textContent='方案已自动保存至本机';}catch{$('saveState').textContent='本机存储已满，请保存方案文件';}}
function checkpoint(){history.push(clone(state));if(history.length>60)history.shift();}
function loadSpec(){const spec={family:$('family').value,depth:+$('depth').value,floor:+$('floor').value};if(spec.family==='XL')spec.floor=1;const stored=saved[key(spec)];state=validPlan(stored,data)?clone(stored):blank(spec);history=[];selected=null;sync();render();}
function sync(){for(const k of ['family','depth','floor'])$(k).value=state.spec[k];$('floor').disabled=state.spec.family==='XL';$('dividerHeight').innerHTML=[20,34.5,82.5].filter(n=>n<=maxHeight(state.spec.floor)).map(n=>`<option value="${n}">${n} mm${n===34.5?' · 1F 满高':n===82.5?' · 2F 满高':''}</option>`).join('');$('dividerHeight').value=state.height;$('pin').value=state.pin;}
function drawLibrary(){const available=data.parts.filter(p=>p.role==='divider'&&p.height===state.height&&p.number<=Math.max(grid().w,grid().d)).sort((a,b)=>a.number-b.number);$('pieceCount').textContent=available.length+' 款';$('pieceList').innerHTML=available.map(p=>`<article class="piece-card" draggable="true" data-n="${p.number}"><svg viewBox="0 0 100 22" aria-hidden="true"><path d="M3 17 L8 6 L92 6 L97 17Z" fill="#e9bc8c" stroke="#c99a68"/><circle cx="20" cy="12" r="2" fill="#fcfcf9"/><circle cx="80" cy="12" r="2" fill="#fcfcf9"/></svg><button aria-label="添加 ${p.number} 号隔板" data-add="${p.number}">＋</button><h3>${p.number} 号${p.number===data.widthNumbers[state.spec.family]?' · 横隔':''}</h3><small>${p.size[0]} mm 长 · ${state.height} mm 高</small></article>`).join('');
 $('pieceList').querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>add(+b.dataset.add));$('pieceList').querySelectorAll('[draggable]').forEach(a=>a.ondragstart=e=>e.dataTransfer.setData('text/plain',a.dataset.n));}
function endpoints(a){return [a.x,a.y,a.x+(a.axis==='h'?a.n:0),a.y+(a.axis==='v'?a.n:0)];}
function board(){const {w,d}=grid(),width={S:164.8,M:254,L:329.6,XL:418.8}[state.spec.family];$('board').setAttribute('viewBox',`-4 -3 ${w+8} ${d+6}`);
 let svg=`<defs><pattern id="holes" width="1" height="1" patternUnits="userSpaceOnUse"><circle cx="0" cy="0" r=".075" fill="#b6c4a7"/></pattern></defs><rect x="-.65" y="-.65" width="${w+1.3}" height="${d+1.3}" rx=".7" fill="#e4eada" stroke="#94a781" stroke-width=".12"/><rect width="${w}" height="${d}" rx=".25" fill="#f3f6ec"/><rect width="${w}" height="${d}" fill="url(#holes)"/><text x="${w/2}" y="-1.5" text-anchor="middle" fill="#91a27f" font-size=".48">${state.spec.family}${state.spec.depth}F${state.spec.floor} · 官方编号规划</text>`;
 for(const a of state.items){const [x,y,x2,y2]=endpoints(a),active=a.id===selected;svg+=`<g class="divider" data-id="${esc(a.id)}" role="button" tabindex="0" aria-label="${a.n}号${a.axis==='h'?'横向':'纵向'}隔板"><path d="M${x} ${y}L${x2} ${y2}" stroke="transparent" stroke-width="1.2"/><path d="M${x} ${y}L${x2} ${y2}" stroke="${active?'#526f3c':'#c59059'}" stroke-width="${active?'.6':'.4'}" stroke-linecap="round"/><path d="M${x} ${y}L${x2} ${y2}" stroke="#edc59a" stroke-width=".24"/>`;
 for(const [px,py] of [[x,y],[x2,y2]]){const wall=a.axis==='h'?(px===0||px===w):(py===0||py===d);if(wall&&a.border!=='none')svg+=`<rect x="${px-.24}" y="${py-.24}" width=".48" height=".48" rx="${a.border==='rounded'?'.2':'.02'}" fill="#a7b49a" stroke="#7e926d" stroke-width=".06"/>`;}
 for(const t of [2/a.n,1-2/a.n])svg+=`<circle cx="${x+(x2-x)*t}" cy="${y+(y2-y)*t}" r=".11" fill="#f8faf3" stroke="#6a8058" stroke-width=".05"/>`;
 svg+=`<text x="${(x+x2)/2}" y="${(y+y2)/2-.38}" text-anchor="middle" font-size=".45" fill="#627b4e">${a.n}号</text></g>`;}
 $('board').innerHTML=svg;$('planName').textContent=`${state.spec.family}${state.spec.depth}F${state.spec.floor} · 隔板规划`;$('drawerSize').textContent=`外箱名义尺寸 ${width} 宽 × ${state.spec.depth*42} 深 × ${state.spec.floor*48} 高 mm。隔板编号范围：横向 ${w}，纵向 ${d}。`;
 const a=state.items.find(i=>i.id===selected);$('selection').innerHTML=a?`<strong>${a.n}号 · ${a.axis==='h'?'横向':'纵向'} · ${state.height} mm 高</strong><span>起点 ${a.x}, ${a.y} · 孔数坐标</span><button id="rotatePiece">旋转 R</button><button id="removePiece">删除</button>`:'选择左侧隔板，或点击已放置的隔板编辑。';if(a){$('rotatePiece').onclick=rotate;$('removePiece').onclick=remove;}
 $('undo').disabled=!history.length;$('clear').disabled=!state.items.length;$('layoutStatus').textContent=state.items.length?`✓ ${state.items.length} 片隔板 · 无越界、重叠或交叉穿插`:'点击 ＋ 添加隔板，或拖入图中摆放';}
const labels={divider:'隔板',straight:'直边端部件',rounded:'圆角端部件',loose:'松配插销',tight:'紧配插销'};
const name=p=>p.role==='divider'?p.number+'号隔板 · '+p.height+' mm':labels[p.role]+(p.height?' · '+p.height+' mm':'');
function bom(){const rows=dividerBOM(state,data);let grams=0,seconds=0,missing=0;for(const r of rows){const e=estimates.records[r.path];if(e?.status==='ok'){grams+=e.grams*r.qty;seconds+=e.seconds*r.qty;}else missing++;}const mins=Math.ceil(seconds/60);$('grams').textContent=(missing?'≥ ':'')+(grams>=1000?(grams/1000).toFixed(2)+' kg':grams.toFixed(1)+' g');$('duration').textContent=(missing?'≥ ':'')+(mins>=60?Math.floor(mins/60)+'小时':'')+(mins%60)+'分';$('bomCount').textContent=state.items.length+' 片隔板 · '+rows.reduce((n,p)=>n+p.qty,0)+' 份打印';$('estimateNote').textContent=`H2D · PLA · 0.4 mm · 0.20 mm · 15% 填充 · 2层墙。${missing?missing+' 种文件未计入估算。':'按原有切片记录与打印份数汇总。'}`;
 $('bomList').innerHTML=rows.length?`<table><thead><tr><th>官方模型 / 文件</th><th>份数</th><th>单份耗材</th></tr></thead><tbody>${rows.map(p=>`<tr><td>${name(p)}<small>${esc(p.path)}</small></td><td>${p.qty}</td><td>${estimates.records[p.path]?.status==='ok'?estimates.records[p.path].grams.toFixed(1)+' g':'暂无记录'}</td></tr>`).join('')}</tbody></table>`:'<p class="muted small">添加隔板后，端部件和插销会一起列出。</p>';$('downloadZip').disabled=busy||!rows.length;$('csv').disabled=!rows.length;}
function render(){board();bom();save();}
function add(n,point){if(state.items.length>=100)return toast('单个方案最多 100 片隔板');const axis=$('axis').value,a={id:crypto.randomUUID(),n,axis,x:point?Math.round(point.x):0,y:point?Math.round(point.y):0,border:$('border').value};if(!point){let found=false;const g=grid();for(let y=0;y<=g.d&&!found;y++)for(let x=0;x<=g.w&&!found;x++){a.x=x;a.y=y;if(fits(a,state.items,g)){found=true;}}if(!found)return toast('没有合适位置，请更换方向、编号或移动已有隔板');}if(!fits(a,state.items,grid()))return toast('此处越界或与已有隔板重叠 / 交叉，请换一个位置');checkpoint();state.items.push(a);selected=a.id;render();}
function rotate(){const a=state.items.find(i=>i.id===selected);if(!a)return;const next={...a,axis:a.axis==='h'?'v':'h'};if(!fits(next,state.items,grid()))return toast('旋转后放不下，请先移动隔板');checkpoint();Object.assign(a,next);render();}
function remove(){if(!selected)return;checkpoint();state.items=state.items.filter(i=>i.id!==selected);selected=null;render();}
function point(e){const p=$('board').createSVGPoint();p.x=e.clientX;p.y=e.clientY;return p.matrixTransform($('board').getScreenCTM().inverse());}
$('board').onpointerdown=e=>{if(e.button!==0)return;const g=e.target.closest('[data-id]');selected=g?.dataset.id||null;if(selected){const a=state.items.find(i=>i.id===selected);drag={before:clone(state),point:point(e),a:clone(a)};$('board').setPointerCapture(e.pointerId);}board();};
$('board').onpointermove=e=>{if(!drag)return;const p=point(e),a={...drag.a,x:Math.round(drag.a.x+p.x-drag.point.x),y:Math.round(drag.a.y+p.y-drag.point.y)};if(fits(a,state.items,grid())){Object.assign(state.items.find(i=>i.id===a.id),a);board();}};
function endDrag(cancel=false){if(!drag)return;if(cancel)state=drag.before;else if(JSON.stringify(state)!==JSON.stringify(drag.before)){history.push(drag.before);}drag=null;render();}
$('board').onpointerup=()=>endDrag();$('board').onpointercancel=()=>endDrag(true);$('board').onlostpointercapture=()=>endDrag();
$('board').ondragover=e=>e.preventDefault();$('board').ondrop=e=>{e.preventDefault();const n=+e.dataTransfer.getData('text/plain');if(data.parts.some(p=>p.role==='divider'&&p.number===n&&p.height===state.height))add(n,point(e));};
for(const id of ['family','depth','floor'])$(id).onchange=()=>{save();loadSpec();drawLibrary();};$('dividerHeight').onchange=()=>{checkpoint();state.height=+$('dividerHeight').value;drawLibrary();render();};$('pin').onchange=()=>{checkpoint();state.pin=$('pin').value;render();};
$('undo').onclick=()=>{if(!history.length)return;state=history.pop();selected=null;sync();drawLibrary();render();};$('clear').onclick=()=>{if(!state.items.length)return;checkpoint();state.items=[];selected=null;render();};$('example').onclick=()=>{checkpoint();state.items=[{id:crypto.randomUUID(),n:grid().w,axis:'h',x:0,y:Math.floor(grid().d/2),border:$('border').value}];selected=state.items[0].id;render();};
document.addEventListener('keydown',e=>{if(/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;if(e.key==='Escape'){endDrag(true);selected=null;board();}if(e.key.toLowerCase()==='r')rotate();if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();remove();}const delta={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]}[e.key],a=state.items.find(i=>i.id===selected);if(a&&delta){e.preventDefault();const next={...a,x:a.x+delta[0],y:a.y+delta[1]};if(fits(next,state.items,grid())){checkpoint();Object.assign(a,next);render();}}});
function download(blob,filename){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);}
function csv(plan=state){return '\ufeff部件,打印份数,源文件\r\n'+dividerBOM(plan,data).map(p=>[name(p),p.qty,p.path].map(s=>'"'+String(s).replaceAll('"','""')+'"').join(',')).join('\r\n');}
$('csv').onclick=()=>download(new Blob([csv()],{type:'text/csv;charset=utf-8'}),key(state.spec)+'-隔板清单.csv');$('savePlan').onclick=()=>download(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),key(state.spec)+'-隔板方案.json');$('importPlan').onclick=()=>$('planInput').click();$('planInput').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const plan=JSON.parse(await f.text());if(!validPlan(plan,data))throw Error('方案规格、模型或排布无效');save();state=plan;history=[];selected=null;sync();drawLibrary();render();toast('已导入隔板方案');}catch(error){toast(error.message);}e.target.value='';};
$('chooseModelDirectory').disabled=false;$('chooseModelDirectory').onclick=()=>$('folderInput').click();$('folderInput').onchange=e=>{try{const result=matchModelDirectory([...e.target.files],cat);linked=result.files;toast('已连接 '+result.stls+' 个模型文件');$('modelDirectoryStatus').innerHTML='<i></i>本地文件已连接';}catch(error){toast(error.message);}e.target.value='';};
try{const r=await fetch('/api/status');if(r.ok)local=(await r.json()).ready===true;}catch{}$('modelDirectoryStatus').innerHTML='<i></i>'+(local?'本机模型库已连接':'本地模型 · 无需上传');
$('downloadZip').onclick=async()=>{busy=true;bom();try{const snapshot=clone(state),rows=dividerBOM(snapshot,data),entries=[];for(const row of rows){let blob=linked.get(row.path);if(!blob&&local){const r=await fetch('/api/file/'+encodeURIComponent(row.path));if(!r.ok)throw Error('模型读取失败：'+row.path);blob=await r.blob();}if(!blob)throw Error('请先选择原始模型目录，缺少 '+row.path);entries.push({name:'print-'+row.qty+'/'+row.path,size:blob.size,stream:()=>blob.stream()});}for(const [name,content] of [['隔板方案.json',JSON.stringify(snapshot,null,2)],['隔板清单.csv',csv(snapshot)],['README.txt','每个 STL 保留一份，print-N 表示需要打印 N 份。隔板与端部件按官方说明安装，每片隔板两根插销。原始模型不缩放。']]){const blob=new Blob([content]);entries.push({name,size:blob.size,stream:()=>blob.stream()});}const chunks=[];await writeZip(entries,{write:b=>chunks.push(b),close:async()=>{}});download(new Blob(chunks,{type:'application/zip'}),key(snapshot.spec)+'-隔板模型.zip');toast('已打包官方模型、方案与清单');}catch(error){toast(error.message);}finally{busy=false;bom();}};
loadSpec();drawLibrary();
